import{_ as e,o as t,c as i,ai as n}from"./chunks/framework.Ci0kozOl.js";const p=JSON.parse('{"title":"Packages","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/architecture/packages.md","filePath":"3.0/architecture/packages.md","lastUpdated":1786015710000}'),o={name:"3.0/architecture/packages.md"};function r(s,a,l,c,d,g){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p><a href="https://laravel.com" target="_blank" rel="noreferrer">Laravel</a> packages are the primary way of adding functionality, and the following features are distributed into packages to enhance the application and allow developers to follow the standard way of developing custom functionality.</p><p>UnoPim comes with a set of powerful default packages that provide essential functionalities out of the box. Below is a list of these default packages along with a brief description of each:</p><h2 id="available-packages-in-unopim" tabindex="-1">Available Packages In UnoPim <a class="header-anchor" href="#available-packages-in-unopim" aria-label="Permalink to &quot;Available Packages In UnoPim&quot;">​</a></h2><h3 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h3><p>The <strong>Admin</strong> package in UnoPim is a core component that provides the administrative interface and functionality for managing various aspects of the platform. It offers a comprehensive dashboard and a set of tools for administrators to efficiently manage products, attributes, categories, and configurations. Here&#39;s a detailed overview of the Admin package in UnoPim:</p><h4 id="key-features-of-the-admin-package" tabindex="-1">Key Features of the Admin Package <a class="header-anchor" href="#key-features-of-the-admin-package" aria-label="Permalink to &quot;Key Features of the Admin Package&quot;">​</a></h4><ul><li><p><strong>Dashboard</strong></p><ul><li>Provides a summary of key metrics related to product information and category management.</li><li>Displays widgets for quick insights into products, attributes, and data updates.</li><li>Channel readiness indicators showing product completeness across channels.</li><li>Product trend charts tracking creation and update activity over time.</li><li>Activity feeds displaying recent product, category, and user actions.</li></ul></li><li><p><strong>Product Management</strong></p><ul><li>Allows administrators to add, edit, and delete product information.</li><li>Supports the management of product attributes, categories, and variants.</li></ul></li><li><p><strong>Configuration and Settings</strong></p><ul><li>Provides a wide range of configuration options to customize the platform’s behavior.</li><li>Includes settings for managing localization, languages, and data formats.</li><li>Allows customization of email templates and system notifications.</li><li>Agentic PIM configuration for AI agent behavior, approval workflows, and auto-enrichment settings.</li></ul></li></ul><h3 id="adminapi" tabindex="-1">AdminApi <a class="header-anchor" href="#adminapi" aria-label="Permalink to &quot;AdminApi&quot;">​</a></h3><p>The <strong>AdminApi</strong> package in UnoPim provides API functionalities for managing administrative operations. It enables the integration of external systems with UnoPim to handle products, categories, and configurations via REST APIs.</p><h4 id="key-features-of-the-adminapi-package" tabindex="-1">Key Features of the AdminApi Package <a class="header-anchor" href="#key-features-of-the-adminapi-package" aria-label="Permalink to &quot;Key Features of the AdminApi Package&quot;">​</a></h4><ul><li><p><strong>Product Management</strong></p><ul><li>API endpoints for creating, editing, and deleting product information.</li><li>Support for managing product attributes and categories programmatically.</li></ul></li><li><p><strong>Configuration and Settings</strong></p><ul><li>API access to platform settings, including languages, locales, and customization options.</li></ul></li></ul><h3 id="attribute" tabindex="-1">Attribute <a class="header-anchor" href="#attribute" aria-label="Permalink to &quot;Attribute&quot;">​</a></h3><p>The <strong>Attribute</strong> package in UnoPim handles all logic related to product attributes and attribute sets. This package allows you to define and organize product information effectively and customize data to enhance search and filtering capabilities.</p><h4 id="key-features-of-the-attribute-package" tabindex="-1">Key Features of the Attribute Package <a class="header-anchor" href="#key-features-of-the-attribute-package" aria-label="Permalink to &quot;Key Features of the Attribute Package&quot;">​</a></h4><ul><li><p><strong>Attribute Management</strong></p><ul><li>Create, edit, and delete product attributes.</li><li>Define various attribute types, such as text, textarea, multiselect, date, and boolean.</li><li>Set validation rules for attributes to ensure data consistency.</li></ul></li><li><p><strong>Attribute Options</strong></p><ul><li>Manage option values for attributes, including sorting and display order.</li></ul></li><li><p><strong>Attribute Family</strong></p><ul><li>Configure attribute families to group related attributes for efficient product data management.</li></ul></li></ul><h3 id="category" tabindex="-1">Category <a class="header-anchor" href="#category" aria-label="Permalink to &quot;Category&quot;">​</a></h3><p>The <strong>Category</strong> package manages the database logic related to product categories. It allows you to define, organize, and manage product categories efficiently, facilitating better categorization and hierarchical structuring of product information.</p><h4 id="key-features-of-the-category-package" tabindex="-1">Key Features of the Category Package <a class="header-anchor" href="#key-features-of-the-category-package" aria-label="Permalink to &quot;Key Features of the Category Package&quot;">​</a></h4><ul><li><strong>Category Management</strong><ul><li>Create, edit, and delete categories.</li><li>Define parent-child relationships to establish a hierarchical category structure.</li><li>Set category attributes such as name, description, and URL keys.</li><li>Enable or disable categories as needed.</li></ul></li></ul><h3 id="completeness" tabindex="-1">Completeness <a class="header-anchor" href="#completeness" aria-label="Permalink to &quot;Completeness&quot;">​</a></h3><p>The <strong>Completeness</strong> package manages the logic related to product completeness scores. It calculates and tracks product completeness, including configuration for calculation and the actual computation, helping ensure complete and accurate product information.</p><h4 id="key-features-of-the-completeness-package" tabindex="-1">Key Features of the Completeness Package <a class="header-anchor" href="#key-features-of-the-completeness-package" aria-label="Permalink to &quot;Key Features of the Completeness Package&quot;">​</a></h4><ul><li><strong>Product Completeness Management</strong><ul><li>Manage configuration for calculating product completeness.</li><li>Calculate product completeness scores on product updates.</li><li>Handle product completeness calculation during bulk updates.</li></ul></li></ul><h3 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h3><p>The <strong>Core</strong> package serves as the foundation for various functionalities and utilities essential for the operation of the UnoPim platform. It provides critical components, settings, configurations, and common helper functions used across other packages.</p><h4 id="key-features-and-components" tabindex="-1">Key Features and Components <a class="header-anchor" href="#key-features-and-components" aria-label="Permalink to &quot;Key Features and Components&quot;">​</a></h4><ul><li><p><strong>Settings and Configurations</strong></p><ul><li>Manages platform-wide configurations such as site name, logo, and localization settings.</li><li>Handles environment-specific configurations for development, staging, and production environments.</li></ul></li><li><p><strong>Common Helper Functions</strong></p><ul><li>Provides utilities for tasks such as data manipulation, file handling, and date/time formatting.</li><li>Includes validation functions for input data, ensuring data integrity.</li></ul></li></ul><h3 id="datagrid" tabindex="-1">Datagrid <a class="header-anchor" href="#datagrid" aria-label="Permalink to &quot;Datagrid&quot;">​</a></h3><p>The <strong>Datagrid</strong> package provides a solution for displaying and managing tabular data within the admin panel. It enables efficient data handling and enhances the user experience with configurable columns, filters, and sorting options.</p><h4 id="key-features-of-the-datagrid-package" tabindex="-1">Key Features of the Datagrid Package <a class="header-anchor" href="#key-features-of-the-datagrid-package" aria-label="Permalink to &quot;Key Features of the Datagrid Package&quot;">​</a></h4><ul><li><p><strong>Dynamic Data Presentation</strong></p><ul><li>Allows administrators to configure columns, filters, and sorting for displaying product data in tables.</li><li>Supports pagination settings to manage large datasets.</li></ul></li><li><p><strong>Advanced Filtering and Sorting</strong></p><ul><li>Enables filtering based on various criteria for refining data views.</li><li>Supports sorting to organize data based on specified attributes.</li></ul></li></ul><h3 id="datatransfer" tabindex="-1">DataTransfer <a class="header-anchor" href="#datatransfer" aria-label="Permalink to &quot;DataTransfer&quot;">​</a></h3><p>The <strong>DataTransfer</strong> package manages data imports and exports, facilitating bulk operations such as importing large volumes of product information. For more details, see the <a href="/2.1/packages/data-transfer.html">DataTransfer documentation</a>.</p><h3 id="debugbar" tabindex="-1">DebugBar <a class="header-anchor" href="#debugbar" aria-label="Permalink to &quot;DebugBar&quot;">​</a></h3><p>The <strong>DebugBar</strong> package includes essential tools for monitoring, analyzing, and debugging the UnoPim platform, ensuring optimal performance during development and troubleshooting.</p><h3 id="elasticsearch" tabindex="-1">ElasticSearch <a class="header-anchor" href="#elasticsearch" aria-label="Permalink to &quot;ElasticSearch&quot;">​</a></h3><p>The <strong>ElasticSearch</strong> package integrates ElasticSearch functionalities into UnoPim, enabling advanced search capabilities and data indexing. It allows for efficient querying and retrieval of product information, enhancing the overall search experience.</p><h3 id="fpc" tabindex="-1">FPC <a class="header-anchor" href="#fpc" aria-label="Permalink to &quot;FPC&quot;">​</a></h3><p>The <strong>FPC (Full Page Cache)</strong> package optimizes the platform’s performance by caching generated pages, reducing server load, and improving response times for administrators.</p><h3 id="historycontrol" tabindex="-1">HistoryControl <a class="header-anchor" href="#historycontrol" aria-label="Permalink to &quot;HistoryControl&quot;">​</a></h3><p>The <strong>HistoryControl</strong> package keeps track of changes made to product data and other critical information, allowing administrators to monitor revisions and revert to previous versions if necessary.</p><h3 id="installer" tabindex="-1">Installer <a class="header-anchor" href="#installer" aria-label="Permalink to &quot;Installer&quot;">​</a></h3><p>The <strong>Installer</strong> package simplifies the installation process of the UnoPim platform, providing an easy setup for database configuration, dependency installation, and environment initialization.</p><h3 id="magicai" tabindex="-1">MagicAI <a class="header-anchor" href="#magicai" aria-label="Permalink to &quot;MagicAI&quot;">​</a></h3><p>The <strong>MagicAI</strong> package integrates AI-based functionalities into UnoPim, offering tools to enhance efficiency and decision-making processes based on product data. Since v2.0.0, MagicAI supports <strong>multi-platform AI provider management</strong> with 10+ providers including OpenAI, Groq, Ollama, Gemini, Anthropic, and more, all configurable through a unified admin interface.</p><h4 id="key-features-of-the-magicai-package" tabindex="-1">Key Features of the MagicAI Package <a class="header-anchor" href="#key-features-of-the-magicai-package" aria-label="Permalink to &quot;Key Features of the MagicAI Package&quot;">​</a></h4><ul><li>Translate product attribute values using AI</li><li>Manage reusable prompts for applying AI across multiple products and attributes</li><li>Configure system prompts and model settings, such as maximum token limits and model personality using a prompt</li><li><strong>Multi-platform support</strong> via the LaravelAiAdapter, allowing seamless switching between AI providers</li><li><strong>Database-backed credential management</strong> for securely storing and managing API keys and provider configurations per platform</li><li>Platform-specific model discovery and validation</li></ul><h3 id="aiagent" tabindex="-1">AiAgent <a class="header-anchor" href="#aiagent" aria-label="Permalink to &quot;AiAgent&quot;">​</a></h3><p>The <strong>AiAgent</strong> package provides an AI-powered conversational interface for managing PIM operations through natural language. It enables administrators to interact with product data, run enrichment tasks, and monitor data quality using an intelligent chat-based workflow.</p><h4 id="key-features-of-the-aiagent-package" tabindex="-1">Key Features of the AiAgent Package <a class="header-anchor" href="#key-features-of-the-aiagent-package" aria-label="Permalink to &quot;Key Features of the AiAgent Package&quot;">​</a></h4><ul><li><strong>AI Agent Chat</strong> with 32+ PIM-specific tools for product management, category operations, attribute handling, and data analysis</li><li><strong>Approval Queue</strong> for reviewing and approving AI-suggested changes before they are applied to product data</li><li><strong>Auto-Enrichment</strong> capabilities for automatically generating and improving product descriptions, translations, and attribute values</li><li><strong>Content Feedback</strong> system allowing users to rate and refine AI-generated content</li><li><strong>Memory System</strong> that retains conversation context and user preferences across sessions</li><li><strong>Quality Monitor</strong> for tracking product data quality scores and identifying areas for improvement</li><li><strong>Token Tracking</strong> to monitor AI usage and costs across providers and sessions</li></ul><h3 id="notification" tabindex="-1">Notification <a class="header-anchor" href="#notification" aria-label="Permalink to &quot;Notification&quot;">​</a></h3><p>The <strong>Notification</strong> package manages system notifications and alerts, enabling administrators to receive automated updates based on product data changes and other key events.</p><h3 id="product" tabindex="-1">Product <a class="header-anchor" href="#product" aria-label="Permalink to &quot;Product&quot;">​</a></h3><p>The <strong>Product</strong> package in UnoPim manages all essential product information, including attributes, variants, and categorization. It allows administrators to create, update, and organize product data efficiently, supporting advanced configurations and real-time updates.</p><h3 id="user" tabindex="-1">User <a class="header-anchor" href="#user" aria-label="Permalink to &quot;User&quot;">​</a></h3><p>The <strong>User</strong> package handles user management, including roles, permissions, and profiles for administrators, ensuring secure access and personalized experiences within the platform.</p><h3 id="webhook" tabindex="-1">Webhook <a class="header-anchor" href="#webhook" aria-label="Permalink to &quot;Webhook&quot;">​</a></h3><p>The <strong>Webhook</strong> package manages product webhook configurations, including enabling or disabling webhook and handling product webhooks triggered by any product changes.</p>',61)])])}const h=e(o,[["render",r]]);export{p as __pageData,h as default};
